import{_ as d,o as r,c as a,a2 as o}from"./chunks/framework.BXzK3EA4.js";const q=JSON.parse('{"title":"시작 프리셋 — 선택형 난이도와 결핍 조합","description":"","frontmatter":{},"headers":[],"relativePath":"world/Starting-Presets.md","filePath":"world/Starting-Presets.md"}'),e={name:"world/Starting-Presets.md"};function h(l,t,n,s,i,b){return r(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="시작-프리셋-—-선택형-난이도와-결핍-조합" tabindex="-1">시작 프리셋 — 선택형 난이도와 결핍 조합 <a class="header-anchor" href="#시작-프리셋-—-선택형-난이도와-결핍-조합" aria-label="Permalink to &quot;시작 프리셋 — 선택형 난이도와 결핍 조합&quot;">​</a></h1><blockquote><p>근거: K-시스템 &quot;빈곤은 하나의 난이도가 아니라 여러 종류의 결핍&quot; [REF:K-START], BB &quot;기원은 시작 보너스가 아니라 회사의 장기 규칙&quot; [REF:BB-ORIGINS]. 각 프리셋은 <strong>결핍의 종류</strong>가 난이도를 만든다 — 숫자 조정이 아니라 &quot;무엇이 없는가&quot;가 다르다.</p></blockquote><blockquote><p>설계 제안이며 현재 선택 가능한 기능 목록이 아니다. 아래 수치는 목표값이고, P0/P1/P2는 구현 우선순위이지 완료 판정이 아니다.</p></blockquote><h2 id="원칙" tabindex="-1">원칙 <a class="header-anchor" href="#원칙" aria-label="Permalink to &quot;원칙&quot;">​</a></h2><ol><li>플레이어는 시작 시 <strong>프리셋을 고른다</strong> — 각각 다른 결핍 조합 = 다른 난이도</li><li>플레이어 캐릭터 생성(이름·성별·외형)은 <strong>모든 프리셋 공통</strong></li><li>동료는 세계 인물(Cast 총람)에서 <strong>프리셋별 필터로 무작위 배치</strong></li><li>프리셋은 장기 규칙을 정한다 — 시작 직후 사라지는 보너스가 아님 [BB]</li></ol><h2 id="프리셋-6종" tabindex="-1">프리셋 (6종) <a class="header-anchor" href="#프리셋-6종" aria-label="Permalink to &quot;프리셋 (6종)&quot;">​</a></h2><h3 id="☀-표준-—-떠돌이-삼인조-normal" tabindex="-1">☀ 표준 — &quot;떠돌이 삼인조&quot; (Normal) <a class="header-anchor" href="#☀-표준-—-떠돌이-삼인조-normal" aria-label="Permalink to &quot;☀ 표준 — &quot;떠돌이 삼인조&quot; (Normal)&quot;">​</a></h3><blockquote><p>어느 역에서도 환영받지 못하는 세 사람. 하룻밤 잠자리를 얻는 것이 오늘의 목표.</p></blockquote><table tabindex="0"><thead><tr><th>항목</th><th>값</th></tr></thead><tbody><tr><td>시작 인원</td><td>3 (지휘관 + 무작위 2)</td></tr><tr><td>보급</td><td>30 (아슬아슬 — 며칠치)</td></tr><tr><td>장비</td><td>최소 (봉·낡은 의복)</td></tr><tr><td>평판</td><td>모든 세력 0 (무관심)</td></tr><tr><td>거점</td><td><strong>없음</strong> — 영등포 대합실에서 하룻밤 허락받은 상태</td></tr><tr><td>장기 규칙</td><td>없음 — 표준 규칙 그대로</td></tr><tr><td>난이도</td><td>★★☆☆☆</td></tr></tbody></table><h3 id="🛡-쉬움-—-전직-자치-순찰대-easy" tabindex="-1">🛡 쉬움 — &quot;전직 자치 순찰대&quot; (Easy) <a class="header-anchor" href="#🛡-쉬움-—-전직-자치-순찰대-easy" aria-label="Permalink to &quot;🛡 쉬움 — &quot;전직 자치 순찰대&quot; (Easy)&quot;">​</a></h3><blockquote><p>무너진 자치회의 옛 순찰대원들. 싸울 줄은 알지만, 옛 동료들은 그들을 배신자로 본다.</p></blockquote><table tabindex="0"><thead><tr><th>항목</th><th>값</th></tr></thead><tbody><tr><td>시작 인원</td><td>4 (지휘관 + 무작위 3, 전원 기본 전투 스킬 보유)</td></tr><tr><td>보급</td><td>50 (여유)</td></tr><tr><td>장비</td><td>양호 (제식 봉·순찰 방패·응급 키트)</td></tr><tr><td>평판</td><td>신도림 자치회 <strong>−3</strong> (배신자 취급), 나머지 0</td></tr><tr><td>거점</td><td>신도림 B1 대합실 구석 사용권 (월 보급 −5)</td></tr><tr><td>장기 규칙</td><td>신도림 자치회와의 관계 회복이 첫 관문. 구원정보 접근 불가</td></tr><tr><td>난이도</td><td>★☆☆☆☆</td></tr></tbody></table><h3 id="💰-경제-—-상인-잔존자-economy" tabindex="-1">💰 경제 — &quot;상인 잔존자&quot; (Economy) <a class="header-anchor" href="#💰-경제-—-상인-잔존자-economy" aria-label="Permalink to &quot;💰 경제 — &quot;상인 잔존자&quot; (Economy)&quot;">​</a></h3><blockquote><p>붕괴 전 물류망의 생존자. 물건은 있지만 지킬 힘이 없다.</p></blockquote><table tabindex="0"><thead><tr><th>항목</th><th>값</th></tr></thead><tbody><tr><td>시작 인원</td><td>3 (지휘관 + 상인 출신 1 + 무작위 1)</td></tr><tr><td>보급</td><td>80 (풍부)</td></tr><tr><td>장비</td><td>상인용 (운반용 카트·저울·교섭 수첩)</td></tr><tr><td>평판</td><td>교역로 세력 +2, 군벌 −1 (약탈 대상)</td></tr><tr><td>거점</td><td>없음 — 이동하며 거래</td></tr><tr><td>장기 규칙</td><td><strong>교역 이윤 +20%</strong> / 전투원 고용 비용 +50% (상인 출신은 싸우지 않음)</td></tr><tr><td>난이도</td><td>★★☆☆☆ (전투 회피 경로)</td></tr></tbody></table><h3 id="⚔-도전-—-탈영-소대-hard" tabindex="-1">⚔ 도전 — &quot;탈영 소대&quot; (Hard) <a class="header-anchor" href="#⚔-도전-—-탈영-소대-hard" aria-label="Permalink to &quot;⚔ 도전 — &quot;탈영 소대&quot; (Hard)&quot;">​</a></h3><blockquote><p>구로 군벌에서 탈영한 전투 소대. 잘 싸우지만, 군벌의 추격자가 뒤에 있다.</p></blockquote><table tabindex="0"><thead><tr><th>항목</th><th>값</th></tr></thead><tbody><tr><td>시작 인원</td><td>5 (지휘관 + 전투원 4)</td></tr><tr><td>보급</td><td>20 (부족 — 탈출하며 거의 잃음)</td></tr><tr><td>장비</td><td>군용 (제식 무기·방어구 — 좋지만 눈에 띔)</td></tr><tr><td>평판</td><td>구로 군벌 <strong>−5</strong> (살해 대상), 나머지 세력 −1 (군인 불신)</td></tr><tr><td>거점</td><td>없음 — 계속 이동해야 함</td></tr><tr><td>장기 규칙</td><td><strong>구로 군벌 추격자</strong>가 주기적으로 스폰. 정착 시 추격 강도 증가</td></tr><tr><td>난이도</td><td>★★★★☆</td></tr></tbody></table><h3 id="🏚-최난-—-고아-무리-very-hard" tabindex="-1">🏚 최난 — &quot;고아 무리&quot; (Very Hard) <a class="header-anchor" href="#🏚-최난-—-고아-무리-very-hard" aria-label="Permalink to &quot;🏚 최난 — &quot;고아 무리&quot; (Very Hard)&quot;">​</a></h3><blockquote><p>지하에서 태어나 지하에서 자란 아이들. 숫자는 많지만 아무것도 모른다.</p></blockquote><table tabindex="0"><thead><tr><th>항목</th><th>값</th></tr></thead><tbody><tr><td>시작 인원</td><td>6 (지휘관 + 미성년 5 — 전원 스킬 없음)</td></tr><tr><td>보급</td><td>10 (극빈)</td></tr><tr><td>장비</td><td>없음 (넝마주움)</td></tr><tr><td>평판</td><td>모든 세력 0 — 단, 의뢰 수주 시 <strong>신뢰도 판정</strong> 필요 (아이들을 믿는 곳 없음)</td></tr><tr><td>거점</td><td>폐쇄된 환기구 안 (은신처 — 시설 없음)</td></tr><tr><td>장기 규칙</td><td>성장 속도 ×2 (배움이 빠름) / 사망 시 사기 타격 ×2 / 의뢰 보상 −30%</td></tr><tr><td>난이도</td><td>★★★★★</td></tr></tbody></table><h3 id="📜-스토리-—-마지막-역장-story" tabindex="-1">📜 스토리 — &quot;마지막 역장&quot; (Story) <a class="header-anchor" href="#📜-스토리-—-마지막-역장-story" aria-label="Permalink to &quot;📜 스토리 — &quot;마지막 역장&quot; (Story)&quot;">​</a></h3><blockquote><p>마지막까지 역을 지킨 노역장과 그를 따르는 소수. 정통성은 있지만 힘이 없다.</p></blockquote><table tabindex="0"><thead><tr><th>항목</th><th>값</th></tr></thead><tbody><tr><td>시작 인원</td><td>3 (지휘관 = 역장 + 무작위 2)</td></tr><tr><td>보급</td><td>40</td></tr><tr><td>장비</td><td>평균</td></tr><tr><td>평판</td><td>영등포 주민 +5 (존경), 군벌 −2 (장애물)</td></tr><tr><td>거점</td><td><strong>영등포 B1 부분 통제권</strong> (시설: 게시판만. 의무실·보급소는 수리 필요)</td></tr><tr><td>장기 규칙</td><td>영등포 수리 비용이 성장 목표. 정통성으로 특정 의뢰 전용 접근. 역 상실 시 게임오버 아님 — 망명자가 됨</td></tr><tr><td>난이도</td><td>★★☆☆☆ (시작은 쉽지만 책임이 무겁다)</td></tr></tbody></table><h2 id="결핍-축-매트릭스" tabindex="-1">결핍 축 매트릭스 <a class="header-anchor" href="#결핍-축-매트릭스" aria-label="Permalink to &quot;결핍 축 매트릭스&quot;">​</a></h2><table tabindex="0"><thead><tr><th>프리셋</th><th>인원</th><th>자원</th><th>장비</th><th>평판</th><th>거점</th><th>특수 압박</th></tr></thead><tbody><tr><td>떠돌이</td><td>보통</td><td>부족</td><td>최소</td><td>중립</td><td>없음</td><td>없음</td></tr><tr><td>순찰대</td><td>많음</td><td>여유</td><td>양호</td><td>일부 적대</td><td>임시</td><td>관계 회복</td></tr><tr><td>상인</td><td>보통</td><td>풍부</td><td>특수</td><td>일부 우호</td><td>없음</td><td>전투 취약</td></tr><tr><td>탈영</td><td>많음</td><td>부족</td><td>최상</td><td>광역 적대</td><td>없음</td><td>추격자</td></tr><tr><td>고아</td><td>최다</td><td>극빈</td><td>없음</td><td>불신</td><td>은신처</td><td>사망 사기 타격·의뢰 보상 페널티</td></tr><tr><td>역장</td><td>보통</td><td>보통</td><td>보통</td><td>일부 존경</td><td><strong>부분 통제</strong></td><td>역 책임</td></tr></tbody></table><h2 id="잔선과-레퍼런스의-대응" tabindex="-1">잔선과 레퍼런스의 대응 <a class="header-anchor" href="#잔선과-레퍼런스의-대응" aria-label="Permalink to &quot;잔선과 레퍼런스의 대응&quot;">​</a></h2><table tabindex="0"><thead><tr><th>설계 요소</th><th>K-시스템</th><th>BB</th><th>채택 방식</th></tr></thead><tbody><tr><td>결핍 = 난이도</td><td>13개 시작 시나리오의 핵심</td><td>—</td><td>결핍 축 매트릭스로 구조화</td></tr><tr><td>장기 규칙</td><td>—</td><td>기원별 고유 규칙</td><td>각 프리셋에 지속 규칙 부여</td></tr><tr><td>세력 관계 시작값</td><td>시작부터 Nameless 세력 존재</td><td>—</td><td>프리셋별 평판 차등</td></tr><tr><td>정착 여부</td><td>3상태(유랑/도시/전초)</td><td>비정착 회사도 성장</td><td>거점 유무를 프리셋으로 선택</td></tr></tbody></table><h2 id="구현-우선순위-poc" tabindex="-1">구현 우선순위 (POC) <a class="header-anchor" href="#구현-우선순위-poc" aria-label="Permalink to &quot;구현 우선순위 (POC)&quot;">​</a></h2><ul><li><strong>P0</strong>: 떠돌이(표준) + 역장(스토리) — 두 개만으로도 &quot;거점 있음 vs 없음&quot; 비교 가능</li><li><strong>P1</strong>: 순찰대(쉬움) + 탈영(도전) — 평판 극단 확인</li><li><strong>P2</strong>: 상인 + 고아 — 경제/성장 특화 경로</li></ul>',30)])])}const c=d(e,[["render",h]]);export{q as __pageData,c as default};
